const schemaParametersBody = `{"oneOf":[{"$ref":"#/$defs/MCPOpenSession"},{"$ref":"#/$defs/MCPListTools"},{"$ref":"#/$defs/MCPCallTool"},{"$ref":"#/$defs/MCPCloseSession"}],"$schema":"https://json-schema.org/draft/2020-12/schema"}`

